#include <WiFi.h>
#include <Wire.h>
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>
#include <DHT.h>
#include <LiquidCrystal_I2C.h>

#define DHTPIN 14
#define DHTTYPE DHT11
DHT dht(DHTPIN, DHTTYPE);
#define PIR_PIN 13
LiquidCrystal_I2C lcd(0x27, 16, 2);

#define TFT_CS -1  
#define TFT_DC 9
#define TFT_RST 10
Adafruit_ST7789 tft = Adafruit_ST7789(TFT_CS, TFT_DC, TFT_RST);

#define SERVO_X_PIN 41
#define SERVO_Y_PIN 42

const char* ssid = "ESP32-S3-Robot";
const char* password = "12345678";
WiFiServer server(80);

void setServo(int pin, int ang) {
  ledcWrite(pin, map(ang, 0, 180, 1638, 8192));
}

void drawFace(String emo) {
  tft.fillScreen(ST7789_BLACK);
  if (emo == "normal") {
    tft.fillCircle(70, 90, 15, ST7789_GREEN);
    tft.fillCircle(170, 90, 15, ST7789_GREEN);
    tft.fillRect(90, 150, 60, 8, ST7789_GREEN);
  } else {
    tft.fillCircle(70, 90, 18, ST7789_RED);
    tft.fillCircle(170, 90, 18, ST7789_RED);
    tft.fillCircle(120, 155, 12, ST7789_RED);
  }
  tft.setCursor(75, 205); tft.setTextColor(ST7789_WHITE); tft.setTextSize(2); tft.print(emo);
}

void setup() {
  Serial.begin(115200);
  dht.begin();
  pinMode(PIR_PIN, INPUT);
  Wire.begin(8, 18);
  lcd.init(); lcd.backlight();
  lcd.setCursor(0, 0); lcd.print("Robot Ready");

  SPI.begin(12, 13, 11, -1);
  tft.init(240, 240, SPI_MODE2);
  tft.setRotation(2);
  drawFace("normal");

  ledcAttach(SERVO_X_PIN, 50, 16);
  ledcAttach(SERVO_Y_PIN, 50, 16);
  setServo(SERVO_X_PIN, 90);
  setServo(SERVO_Y_PIN, 90);

  WiFi.softAP(ssid, password);
  server.begin();
}

void loop() {
  float h = dht.readHumidity();
  float t = dht.readTemperature();
  int motion = digitalRead(PIR_PIN);

  lcd.setCursor(0, 1);
  if (!isnan(h) && !isnan(t)) {
    lcd.print("T:"); lcd.print((int)t); lcd.print("C H:"); lcd.print((int)h); lcd.print("% ");
  } else {
    lcd.print("DHT Error     ");
  }

  if (motion == HIGH) {
    lcd.print("Motion!");
    drawFace("motion");
    setServo(SERVO_X_PIN, 45); delay(250);
    setServo(SERVO_X_PIN, 135); delay(250);
    setServo(SERVO_X_PIN, 90);
  } else {
    lcd.print("Safe   ");
    drawFace("normal");
  }

  WiFiClient client = server.available();
  if (client) {
    client.println("HTTP/1.1 200 OK");
    client.println("Content-Type: text/html; charset=utf-8");
    client.println("");
    client.println("<h2>ESP32-S3 Robot</h2>");
    client.stop();
  }
  delay(1000);
}
